import{_ as o,o as t,c as s,ag as n}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-31（材料 / 二维材料 · 数据驱动发现 MXenes）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/materials/science-daily-2026-10-31-materials.md","filePath":"topics/materials/science-daily-2026-10-31-materials.md"}'),i={name:"topics/materials/science-daily-2026-10-31-materials.md"};function r(a,e,c,l,d,g){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="科学日报-·-2026-10-31-材料-二维材料-·-数据驱动发现-mxenes" tabindex="-1">科学日报 · 2026-10-31（材料 / 二维材料 · 数据驱动发现 MXenes） <a class="header-anchor" href="#科学日报-·-2026-10-31-材料-二维材料-·-数据驱动发现-mxenes" aria-label="Permalink to &quot;科学日报 · 2026-10-31（材料 / 二维材料 · 数据驱动发现 MXenes）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-31.md</code> — 第50期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-materials</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-31-材料-·-1-1-数据驱动发现-快速合成-mxenes——几分钟内造出新型二维材料-含-11-种稀土-mxene" tabindex="-1">科学日报 2026-10-31（材料 · 1/1）：数据驱动发现 + 快速合成 MXenes——几分钟内造出新型二维材料，含 11 种稀土 MXene <a class="header-anchor" href="#科学日报-2026-10-31-材料-·-1-1-数据驱动发现-快速合成-mxenes——几分钟内造出新型二维材料-含-11-种稀土-mxene" aria-label="Permalink to &quot;科学日报 2026-10-31（材料 · 1/1）：数据驱动发现 + 快速合成 MXenes——几分钟内造出新型二维材料，含 11 种稀土 MXene&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-31.md</code> ｜ DOI: 10.1126/science.aeh5957 ｜ Science (2026)</p></blockquote><ul><li>问题：<strong>MXenes</strong>（二维过渡金属碳化物/氮化物）是一类<strong>快速扩张</strong>的材料家族，但<strong>可规模化的合成路线仍然有限</strong>；而且历史文献暗示存在一个<strong>更大、基本未被探索的化学空间</strong>——即「已有数据里可能早就藏着没被认出来的 MXene」。</li><li>方法：用<strong>机器学习辅助的数据库挖掘</strong>找出「隐藏的」多层 MXenes，先做<strong>筛选</strong>；再用一种<strong>快速、可放大的自蔓延高温合成法</strong>（<strong>无需持续外部加热、数分钟内完成</strong>）合成候选。</li><li>结果（实测）： <ul><li>筛选出 <strong>33 个「其实早已合成、却未被识别为 MXene」的候选物</strong>（对存量数据的重新识别）；</li><li>据此合成出 <strong>7 种多层 MXene</strong>；</li><li>进一步实现 <strong>11 种此前从未探索的稀土基 MXene</strong>（M = Pr、Nd、Sm、Gd、Tb、Ho、Tm）；</li><li>实验与建模提示该家族普遍呈<strong>半导体行为</strong>，并具有<strong>多样的磁态</strong>。</li></ul></li><li>洞察（对本库 <code>materials</code> × <code>ai-system-architecture</code> 的 ML 辅助发现）： <ol><li><strong>「先重新识别存量数据，再动手合成」＝一批免费候选</strong> —— 33 个候选不是新合成的，而是<strong>从旧样品/旧文献里「重新归类」出来的</strong>。判据：<strong>当某类材料的化学空间被认为巨大时，第一步先跑一遍数据库挖掘，把「已合成但未命名/未识别」的相捞出来，合成预算只花在筛选后的少数上。</strong> 这与 10-30 硫化铋「识别出成熟材料里此前未被利用的性质」同族——<strong>存量材料/数据里常藏着下一批成果。</strong></li><li><strong>「把能耗瓶颈从『持续外部加热』改成『自传播』」</strong> —— 自蔓延高温合成<strong>几分钟完成、无需持续供热</strong>，把「可放大」与「可持续」同时拿下。判据：<strong>当一个合成的瓶颈是「要一直加热/一直供电」，去找自传播/自供能的反应路径，而不是加大外部功率。</strong> 与库内母题「<strong>改路径/换通道优于加力度</strong>」一致。</li><li><strong>一句话定位</strong>：把 <code>materials</code> 的二维材料主线从「已知 MXene 的改性」扩到「<strong>稀土 MXene 这一沿元素维度新开的空间 + 数据驱动发现流程</strong>」。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/materials/index.md</code> ｜ <code>topics/physics/index.md</code> ｜ 第50期 科学板块</p></blockquote><p>关键词：科学日报第50期、MXenes、二维过渡金属碳化物氮化物、机器学习辅助数据库挖掘、33 个已合成未被识别候选、多层 MXene、自蔓延高温合成、无需持续外部加热、数分钟、稀土 MXene、Pr Nd Sm Gd Tb Ho Tm、半导体行为、多样磁态、数据驱动材料发现、重新识别存量数据、存量材料藏成果、改路径优于加力度、可持续合成、加速材料发现</p><p>关联：<code>topics/materials/index.md</code>、<code>topics/materials/science-daily-2026-10-30-materials.md</code>（硫化铋伪直接带隙）、<code>topics/materials/science-daily-2026-10-29-materials.md</code>（碳戊搭烯纳米带 / 硅酮解聚）、<code>topics/physics/index.md</code>、<code>topics/ai-system-architecture/index.md</code>（ML 辅助发现）</p>',10)])])}const u=o(i,[["render",r]]);export{p as __pageData,u as default};
